+-- Main job queue for internal processing
+CREATE TABLE IF NOT EXISTS jobs (
+  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
+  payload TEXT NOT NULL,
+  status TEXT NOT NULL DEFAULT 'ready',
+  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
+  claimed_at TIMESTAMP,
+  completed_at TIMESTAMP
+);
+
+-- Notifications event queue for external consumption by the notifications service
+CREATE TABLE IF NOT EXISTS notifications_queue (
+  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
+  payload TEXT NOT NULL,
+  status TEXT NOT NULL DEFAULT 'pending',
+  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
+  claimed_at TIMESTAMP,
+  sent_at TIMESTAMP
+);
+
+-- Indexes for efficient polling
+CREATE INDEX IF NOT EXISTS idx_jobs_status_created ON jobs (status, created_at) WHERE status = 'ready';
+CREATE INDEX IF NOT EXISTS idx_notifications_status_created ON notifications_queue (status, created_at) WHERE status = 'pending';
