+import { pool } from "./pool.ts";
+
+export interface NotificationEvent {
+  id: string;
+  payload: string;
+}
+
+export const enqueueNotification = async (payload: string): Promise<void> => {
+  await pool.query(
+    "INSERT INTO notifications_queue (payload, status) VALUES ($1, 'pending')",
+    [payload],
+  );
+};
+
+export const enqueueNotificationWithClient = async (client: any, payload: string): Promise<void> => {
+  await client.query(
+    "INSERT INTO notifications_queue (payload, status) VALUES ($1, 'pending')",
+    [payload],
+  );
+};
+
+export const claimNextNotification = async (): Promise<NotificationEvent | null> => {
+  const result = await pool.query(
+    "SELECT id, payload FROM notifications_queue WHERE status = 'pending' ORDER BY created_at LIMIT 1",
+  );
+  const row = result.rows[0];
+  if (row === undefined) return null;
+  await pool.query(
+    "UPDATE notifications_queue SET status = 'claimed', claimed_at = NOW() WHERE id = $1",
+    [row.id],
+  );
+  return { id: row.id, payload: row.payload };
+};
+
+export const markNotificationSent = async (eventId: string): Promise<boolean> => {
+  const result = await pool.query(
+    "UPDATE notifications_queue SET status = 'sent', sent_at = NOW() WHERE id = $1 RETURNING id",
+    [eventId],
+  );
+  return result.rows.length > 0;
+};
