+import http from "http";
+import { claimNextNotification, markNotificationSent } from "./notifications.ts";
+
+export const createServer = (port: number): void => {
+  const server = http.createServer(async (req, res) => {
+    if (req.method === "GET" && req.url === "/notifications/next") {
+      try {
+        const event = await claimNextNotification();
+        res.writeHead(200, { "Content-Type": "application/json" });
+        res.end(JSON.stringify(event || { event: null }));
+      } catch (error) {
+        res.writeHead(500, { "Content-Type": "application/json" });
+        res.end(JSON.stringify({ error: "Failed to claim notification" }));
+      }
+      return;
+    }
+
+    const notificationAckMatch = req.url?.match(/^\/notifications\/([^/]+)\/ack$/);
+    if (req.method === "POST" && notificationAckMatch) {
+      const eventId = notificationAckMatch[1];
+      try {
+        const success = await markNotificationSent(eventId);
+        if (success) {
+          res.writeHead(200, { "Content-Type": "application/json" });
+          res.end(JSON.stringify({ success: true }));
+        } else {
+          res.writeHead(404, { "Content-Type": "application/json" });
+          res.end(JSON.stringify({ error: "Event not found" }));
+        }
+      } catch (error) {
+        res.writeHead(500, { "Content-Type": "application/json" });
+        res.end(JSON.stringify({ error: "Failed to acknowledge notification" }));
+      }
+      return;
+    }
+
+    res.writeHead(404, { "Content-Type": "application/json" });
+    res.end(JSON.stringify({ error: "Not found" }));
+  });
+
+  server.listen(port, () => {
+    console.log(`Notifications API server listening on port ${port}`);
+  });
+};
